.ds-primary { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 40px; padding: 10px 14px; border: 1px solid var(--accent-muted, #A92924); border-radius: var(--radius-xs, 4px); background: var(--accent-muted, #A92924); color: var(--button-text, #FFFFFF); font-family: var(--font-sans, "Segoe UI", "Microsoft YaHei UI", system-ui, sans-serif); font-size: var(--fs-body, 14px); font-weight: 600; line-height: 1.3; cursor: pointer; transition: background-color var(--motion-fast, 160ms) var(--ease-out, cubic-bezier(0.16, 1, 0.3, 1)), border-color var(--motion-fast, 160ms) ease; }
