.ds-field { display: flex; flex-direction: column; gap: 6px; min-width: 0; max-width: 100%; color: var(--text, #F4F7FA); font-family: var(--font-sans, "Segoe UI", "Microsoft YaHei UI", system-ui, sans-serif); }
.ds-field-label { font-size: var(--fs-label, 12px); font-weight: 700; line-height: 1.3; }
.ds-input { display: block; box-sizing: border-box; min-width: 0; min-height: 40px; padding: 10px 12px; border: 1px solid var(--control-line, #657483); border-radius: var(--radius-xs, 4px); color: var(--text, #F4F7FA); background: var(--surface, #14191F); font-family: var(--font-mono, Consolas, "Cascadia Mono", ui-monospace, monospace); font-size: var(--fs-data, 13px); font-variant-numeric: tabular-nums; caret-color: var(--accent, #D83D35); transition: border-color var(--motion-fast, 160ms) ease, background-color var(--motion-fast, 160ms) ease; }
.ds-input::placeholder { color: var(--text-secondary, #A9B4BF); opacity: 1; }
.ds-input:hover:not(:disabled) { border-color: var(--accent, #D83D35); }
