.ds-input[aria-invalid="true"] { border-color: var(--danger, #F0645C); }
.ds-input:disabled { color: var(--text-secondary, #A9B4BF); background: var(--surface-2, #222A33); border-color: var(--line, #303943); cursor: default; }
.ds-field-hint { font-size: var(--fs-caption, 12px); color: var(--text-secondary, #A9B4BF); line-height: 1.6; overflow-wrap: anywhere; }
