.ds-nav-link { display: flex; align-items: center; gap: 10px; min-height: 42px; padding: 0 12px; border-radius: var(--radius-sm, 6px); color: var(--text-secondary, #A9B4BF); font-size: 13px; font-weight: 650; line-height: 1.3; text-decoration: none; transition: color var(--motion-fast, 160ms) ease, background-color var(--motion-fast, 160ms) ease; }
.ds-nav-link:hover { color: var(--text, #F4F7FA); background: var(--surface-2, #222A33); }
.ds-nav-link[aria-current="page"] { color: var(--accent-text, #FF8A80); background: var(--accent-soft, rgba(216, 61, 53, 0.14)); }
