.ds-nav-link svg { flex: 0 0 auto; }
@media (max-width: 768px) { .ds-nav { grid-template-columns: repeat(3, minmax(0, 1fr)); } .ds-nav-link { flex-direction: column; justify-content: center; gap: 4px; min-height: var(--touch-secondary, 44px); padding: 8px 4px; } }
