.ds-badges { display: flex; flex-wrap: wrap; gap: 6px; font-family: var(--font-sans, "Segoe UI", "Microsoft YaHei UI", system-ui, sans-serif); }
.ds-badge { display: inline-flex; align-items: center; gap: 4px; padding: 3px 7px; border: 1px solid var(--line, #303943); border-radius: var(--radius-xs, 4px); background: var(--surface-2, #222A33); color: var(--text-secondary, #A9B4BF); font-size: var(--fs-caption, 12px); font-weight: 600; line-height: 1.4; white-space: nowrap; }
.ds-badge[data-state="current"] { color: var(--text, #F4F7FA); background: var(--accent-soft, rgba(216, 61, 53, 0.14)); }
.ds-badge[data-state="dirty"] { color: var(--text, #F4F7FA); background: color-mix(in srgb, var(--warning, #E7A33D) 14%, var(--surface-2, #222A33)); }
.ds-badge[data-state="success"] { color: var(--text, #F4F7FA); background: color-mix(in srgb, var(--success, #35B779) 14%, var(--surface-2, #222A33)); }

.ds-evidence { min-width: 0; border: 1px solid var(--line, #303943); border-radius: var(--radius-md, 8px); background: var(--surface, #14191F); color: var(--text, #F4F7FA); font-family: var(--font-sans, "Segoe UI", "Microsoft YaHei UI", system-ui, sans-serif); }
.ds-evidence-head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 8px; padding: 16px; border-bottom: 1px solid var(--line, #303943); }
.ds-evidence-head h3 { margin: 0; font-size: var(--fs-title, 18px); font-weight: 700; line-height: 1.25; }
.ds-evidence-head span { color: var(--text-secondary, #A9B4BF); font-size: var(--fs-caption, 12px); line-height: 1.5; }
.ds-evidence-rows { margin: 0; padding: 0 16px; }
.ds-evidence-rows > div { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); gap: 16px; padding: 12px 0; border-bottom: 1px solid var(--line-soft, rgba(255, 255, 255, 0.075)); }
.ds-evidence-rows > div:last-child { border-bottom: 0; }
.ds-evidence-rows dt { color: var(--text-secondary, #A9B4BF); font-size: var(--fs-label, 12px); line-height: 1.5; }
.ds-evidence-rows dd { margin: 0; font-family: var(--font-mono, Consolas, "Cascadia Mono", ui-monospace, monospace); font-size: var(--fs-data, 13px); font-weight: 500; line-height: 1.5; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.ds-evidence-rows .ds-missing { color: var(--text-tertiary, #A9B4BF); font-family: var(--font-sans, "Segoe UI", "Microsoft YaHei UI", system-ui, sans-serif); font-size: var(--fs-label, 12px); font-weight: 400; }

.ds-ghost { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 40px; padding: 9px 12px; border: 1px solid var(--control-line, #657483); border-radius: var(--radius-xs, 4px); background: transparent; color: var(--accent-text, #FF8A80); font-family: var(--font-sans, "Segoe UI", "Microsoft YaHei UI", system-ui, sans-serif); font-size: var(--fs-body, 14px); font-weight: 600; line-height: 1.3; cursor: pointer; transition: background-color var(--motion-fast, 160ms) ease, border-color var(--motion-fast, 160ms) ease; }
