@media (max-width: 768px) { .ds-ghost { min-height: var(--touch-secondary, 44px); } }
@media (prefers-reduced-motion: reduce) { .ds-ghost { transition: none; } }
.ds-report { min-width: 0; overflow: hidden; border: 1px solid var(--line, #303943); border-radius: var(--radius-md, 8px); background: var(--surface, #14191F); color: var(--text, #F4F7FA); font-family: var(--font-sans, "Segoe UI", "Microsoft YaHei UI", system-ui, sans-serif); }
.ds-report-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-4, 16px); padding: var(--space-5, 20px) var(--space-6, 24px); border-bottom: 1px solid var(--line, #303943); }
.ds-report-head > div { min-width: 0; }
.ds-report-head h3 { display: flex; flex-wrap: wrap; align-items: baseline; gap: 8px; margin: 0; font-size: var(--fs-headline, 20px); line-height: 1.5; overflow-wrap: anywhere; }
.ds-report-symbol { color: var(--text-secondary, #A9B4BF); font-family: var(--font-mono, Consolas, "Cascadia Mono", ui-monospace, monospace); font-size: var(--fs-body, 14px); font-weight: 500; }
.ds-report-head p { margin: 4px 0 0; color: var(--text-secondary, #A9B4BF); font-size: var(--fs-caption, 12px); line-height: 1.6; }
.ds-report-head time { font-variant-numeric: tabular-nums; }
.ds-report-head .ds-ghost { flex: 0 0 auto; white-space: nowrap; }
.ds-report-body { padding: var(--space-5, 20px) var(--space-6, 24px); }
.ds-report-lead { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr); align-items: stretch; gap: var(--space-6, 24px); padding-bottom: var(--space-5, 20px); border-bottom: 1px solid var(--line, #303943); }
.ds-report-verdict { position: relative; align-self: center; padding-left: var(--space-4, 16px); }
.ds-report-verdict::before { position: absolute; top: 8px; left: 0; width: 6px; height: 6px; border-radius: 50%; background: var(--warning, #E7A33D); content: ""; }
.ds-report-verdict h4 { margin: 0; font-size: var(--fs-headline, 20px); line-height: 1.5; text-wrap: balance; }
.ds-report-verdict p { max-width: 75ch; margin: 8px 0 0; color: var(--text-secondary, #A9B4BF); font-size: var(--fs-body, 14px); line-height: 1.7; overflow-wrap: anywhere; }
.ds-report-metrics { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); margin: 0; padding: 0; }
.ds-report-metrics > div { min-width: 0; padding: 12px 16px; border-left: 1px solid var(--line-soft, rgba(255, 255, 255, 0.075)); }
.ds-report-metrics > div:nth-child(odd) { border-left: 0; }
.ds-report-metrics > div:nth-child(n+3) { border-top: 1px solid var(--line-soft, rgba(255, 255, 255, 0.075)); }
.ds-report-metrics dt { color: var(--text-tertiary, #A9B4BF); font-size: var(--fs-caption, 12px); font-weight: 600; line-height: 1.5; }
.ds-report-metrics dd { margin: 4px 0 0; color: var(--text, #F4F7FA); font-family: var(--font-mono, Consolas, "Cascadia Mono", ui-monospace, monospace); font-size: var(--fs-title, 18px); font-weight: 700; line-height: 1.5; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.ds-report-metrics .ds-report-score { color: var(--score, #F3C451); }
.ds-report-metrics .ds-report-missing { color: var(--text-tertiary, #A9B4BF); font-family: var(--font-sans, "Segoe UI", "Microsoft YaHei UI", system-ui, sans-serif); font-size: var(--fs-label, 12px); font-weight: 400; }
.ds-report-boundary { margin: 12px 0 0; color: var(--text-secondary, #A9B4BF); font-size: var(--fs-caption, 12px); line-height: 1.6; }
@media (max-width: 768px) { .ds-report-head { align-items: stretch; flex-direction: column; padding: 16px; } .ds-report-head .ds-ghost { align-self: flex-start; } .ds-report-body { padding: 16px; } .ds-report-lead { grid-template-columns: minmax(0, 1fr); gap: 12px; } }

